package com.happypix.booth

import android.media.AudioAttributes
import android.media.SoundPool
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod

/**
 * Interaction tones, played from res/raw WAV files.
 *
 * The files are generated by scripts/generate_tones.py from the same
 * frequencies, durations and decay curve the Electron kiosk synthesises with
 * WebAudio, so the two clients sound identical. Keep the names in sync with
 * src/utils/SoundManager.ts.
 */
class SimpleSoundModule(reactContext: ReactApplicationContext) : ReactContextBaseJavaModule(reactContext) {

    private val soundPool: SoundPool = SoundPool.Builder()
        .setMaxStreams(6)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    private val soundIds = mutableMapOf<String, Int>()
    private val loaded = mutableSetOf<Int>()

    init {
        soundPool.setOnLoadCompleteListener { _, sampleId, status ->
            if (status == 0) loaded.add(sampleId)
        }
        NAMES.forEach { name ->
            val resId = reactApplicationContext.resources
                .getIdentifier(name, "raw", reactApplicationContext.packageName)
            if (resId != 0) {
                soundIds[name] = soundPool.load(reactApplicationContext, resId, 1)
            }
        }
    }

    override fun getName(): String = "SimpleSound"

    /** Play one cue. Unknown names are ignored, never thrown. */
    @ReactMethod
    fun play(name: String) {
        val id = soundIds[name] ?: return
        soundPool.play(id, 1.0f, 1.0f, 1, 0, 1.0f)
    }

    /** Stop every cue in flight (used when a guest walks away mid-flow). */
    @ReactMethod
    fun stopAll() {
        soundPool.autoPause()
        soundPool.autoResume()
    }

    override fun invalidate() {
        soundPool.release()
        super.invalidate()
    }

    private companion object {
        val NAMES = listOf("click", "select", "countdown", "shutter", "success", "beep")
    }
}
